# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: fold
def fold(xs, offset=1):
    return [v + offset for v in xs]

# region: intake
def intake(xs, factor=10):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    return [v * v for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: emit
def emit(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(shape(digest(intake(fold(render(raw))))))

